def run(self):
    ''' Run indefinitely
    '''
    while True: #TODO: get signal from Link is run vs pause vs stop
        try:
            self.runAcquirer()
            if self.done:
                logger.info('Acquirer is exiting')
                return
        except Exception as e:
            logger.error('Acquirer exception during run: {}'.format(e))
            break
